  q:"Q108 \u00b7 Does a POCI asset have stages?",
  tags:["account", "acquisition", "allowance", "asset", "charge", "chart", "credit", "debit", "deterioration", "discount", "distressed", "ecl", "expected", "forgiveness", "gl", "have", "impaired", "impairment", "increase", "irrecoverable", "je", "journal", "journals", "ledger", "loss", "mapping", "off", "originated", "poci", "posting", "provision", "purchased", "recoveries", "recovery", "reserve", "sicr", "significant", "stage", "stage1", "stage2", "stage3", "stages", "staging", "transfer", "write", "writeoff"],
